package pt.brunobonito.cr3paracr2;

import android.app.*; import android.os.*; import android.content.*; import android.content.res.ColorStateList;
import android.graphics.Color; import android.net.Uri; import android.provider.DocumentsContract; import android.util.TypedValue;
import android.view.*; import android.widget.*; import java.util.*;
import com.google.android.material.button.MaterialButton; import com.google.android.material.card.MaterialCardView;
import com.google.android.material.dialog.MaterialAlertDialogBuilder; import com.google.android.material.progressindicator.LinearProgressIndicator; import com.google.android.material.textfield.TextInputEditText;
import com.google.android.material.textfield.TextInputLayout;
import androidx.activity.ComponentActivity;
import androidx.work.*; import androidx.lifecycle.Observer; import java.util.concurrent.TimeUnit;

public class MainActivity extends ComponentActivity {
 static final int PICK=7, EXPORT=8; TextView status; MaterialButton choose; CheckBox recursive; RadioGroup modes;
 LinearLayout manual; TextInputEditText fromInput,toInput,prefixInput,suffixInput; Spinner conflict; String from="cr3",to="cr2";
 Dialog progress; LinearProgressIndicator wave; UUID activeWork; String lastReport=""; TextView progressTitle,progressRule,percent; List<RenameRecord> lastChanges=new ArrayList<>();
 static class Candidate { Uri dir,item; String oldName,newName; boolean conflict; Candidate(Uri d,Uri i,String o,String n,boolean c){dir=d;item=i;oldName=o;newName=n;conflict=c;} }
 static class RenameRecord { Uri dir,item; String before,after; RenameRecord(Uri d,Uri i,String b,String a){dir=d;item=i;before=b;after=a;} }

 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.TRANSPARENT);buildUi();}
 void buildUi(){ScrollView sv=new ScrollView(this);sv.setFillViewport(true);sv.setBackgroundColor(surface());LinearLayout page=col();page.setPadding(dp(20),statusBar()+dp(20),dp(20),dp(30));sv.addView(page);
  TextView brand=txt("RAW RENAME",13,true);brand.setTextColor(primary());page.addView(brand,lp(0,16));page.addView(txt("Renomeia extensões com controlo.",32,true),lp(0,10));TextView intro=txt("Pré-visualiza, resolve conflitos e desfaz a última operação.",16,false);intro.setTextColor(onSurfaceVariant());page.addView(intro,lp(0,22));
  LinearLayout rule=col();MaterialCardView ruleShell=card(rule);TextView s1=txt("01  DEFINIR REGRA",12,true);s1.setTextColor(primary());rule.addView(s1,lp(0,12));modes=new RadioGroup(this);modes.setOrientation(RadioGroup.VERTICAL);modes.addView(radio("CR3  →  CR2",101,true));modes.addView(radio("CR2  →  CR3",102,false));modes.addView(radio("Extensões personalizadas",103,false));rule.addView(modes);
  manual=col();manual.setVisibility(View.GONE);TextInputLayout fromLayout=inputLayout("Origem","Ex.: nef",true); TextInputLayout toLayout=inputLayout("Destino","Ex.: dng",false); manual.addView(fromLayout,lp(8,10)); manual.addView(toLayout,lp(0,4));rule.addView(manual);modes.setOnCheckedChangeListener((g,id)->{manual.setVisibility(id==103?View.VISIBLE:View.GONE);if(id==101){from="cr3";to="cr2";}if(id==102){from="cr2";to="cr3";}});page.addView(ruleShell,lp(0,16));
  LinearLayout opts=col();MaterialCardView optsShell=card(opts);TextView s2=txt("02  OPÇÕES",12,true);s2.setTextColor(primary());opts.addView(s2,lp(0,12));recursive=new CheckBox(this);recursive.setText("Incluir subpastas");recursive.setTextColor(onSurface());recursive.setButtonTintList(ColorStateList.valueOf(primary()));opts.addView(recursive,lp(0,12));opts.addView(txt("Se o ficheiro de destino já existir",14,true),lp(0,8));conflict=new Spinner(this);String[] policies={"Ignorar o ficheiro","Adicionar sufixo _1, _2…","Cancelar toda a operação"};conflict.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,policies));opts.addView(conflict,new LinearLayout.LayoutParams(-1,dp(52))); opts.addView(txt("Regras opcionais de nome",14,true),lp(14,8)); TextInputLayout prefixLayout=inputLayout("Prefixo","Ex.: campanha_",true); prefixInput=(TextInputEditText)prefixLayout.getEditText(); TextInputLayout suffixLayout=inputLayout("Sufixo","Ex.: _editado",false); suffixInput=(TextInputEditText)suffixLayout.getEditText(); opts.addView(prefixLayout,lp(0,8)); opts.addView(suffixLayout,lp(0,4)); page.addView(optsShell,lp(0,16));
  choose=new MaterialButton(this);choose.setText("Selecionar pasta e pré-visualizar");choose.setTextColor(onPrimary());choose.setBackgroundTintList(ColorStateList.valueOf(primary()));choose.setCornerRadius(dp(20));choose.setOnClickListener(v->pick());page.addView(choose,new LinearLayout.LayoutParams(-1,dp(58)));
  TextView warning=txt("Ao mudar entre formatos RAW, a app altera apenas o nome da extensão. Os dados internos não são convertidos e algumas aplicações podem deixar de reconhecer o ficheiro.",14,false);warning.setTextColor(onSecondaryContainer());warning.setPadding(dp(18),dp(16),dp(18),dp(16));warning.setBackground(round(secondaryContainer(),20));page.addView(warning,lp(18,16));status=txt("Pronto para começar",14,true);status.setTextColor(onSurfaceVariant());page.addView(status);setContentView(sv);
 }
 void pick(){if(modes.getCheckedRadioButtonId()==103){from=clean(fromInput.getText().toString());to=clean(toInput.getText().toString());if(!from.matches("[A-Za-z0-9]{1,10}")||!to.matches("[A-Za-z0-9]{1,10}")||from.equalsIgnoreCase(to)){error("Indica extensões diferentes e válidas, sem espaços. Ex.: nef e dng.");return;}}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(195);startActivityForResult(i,PICK);}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==EXPORT&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(java.io.OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(lastReport.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){error("Não foi possível exportar o relatório.");}return;}if(r!=PICK||result!=RESULT_OK||data==null||data.getData()==null)return;Uri tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,data.getFlags()&3);}catch(Exception ignored){}choose.setEnabled(false);status.setText("A analisar ficheiros ."+from+"…");new Thread(()->{List<Candidate> list=new ArrayList<>();scan(DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree)),recursive.isChecked(),list);runOnUiThread(()->showPreview(tree,list));}).start();}
 void scan(Uri dir,boolean recurse,List<Candidate> out){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(dir,DocumentsContract.getDocumentId(dir));String[] cols={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE};try(android.database.Cursor c=getContentResolver().query(children,cols,null,null,null)){if(c==null)return;while(c.moveToNext()){String id=c.getString(0),name=c.getString(1),mime=c.getString(2);Uri item=DocumentsContract.buildDocumentUriUsingTree(dir,id);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){if(recurse)scan(item,true,out);}else if(name!=null&&name.toLowerCase(Locale.ROOT).endsWith("."+from.toLowerCase(Locale.ROOT))){String target=name.substring(0,name.length()-from.length())+caseExt(name,to,from);boolean exists=exists(dir,target);if(exists&&conflict.getSelectedItemPosition()==1)target=unique(dir,target);out.add(new Candidate(dir,item,name,target,exists));}}}catch(Exception ignored){}}
 void showPreview(Uri tree,List<Candidate> list){choose.setEnabled(true);int conflicts=0;for(Candidate c:list)if(c.conflict)conflicts++;StringBuilder body=new StringBuilder("Conversão: .").append(from.toUpperCase()).append(" → .").append(to.toUpperCase()).append("\n\nEncontrados: ").append(list.size()).append("\nConflitos: ").append(conflicts).append("\n\nPré-visualização:\n");for(int i=0;i<Math.min(10,list.size());i++){Candidate c=list.get(i);body.append("\n").append(c.oldName).append("  →  ").append(c.newName);if(c.conflict&&conflict.getSelectedItemPosition()==0)body.append("  (ignorado)");}if(list.size()>10)body.append("\n\n+").append(list.size()-10).append(" ficheiros");
  if(list.isEmpty()){new MaterialAlertDialogBuilder(this).setTitle("Nenhum ficheiro encontrado").setMessage("Não foram encontrados ficheiros ."+from+" na pasta selecionada.").setPositiveButton("OK",null).show();status.setText("Nenhum ficheiro encontrado");return;}
  if(conflicts>0&&conflict.getSelectedItemPosition()==2){new MaterialAlertDialogBuilder(this).setTitle("Operação cancelada por conflitos").setMessage(body.toString()).setPositiveButton("OK",null).show();status.setText("Existem conflitos por resolver");return;}
  new MaterialAlertDialogBuilder(this).setTitle("Confirmar pré-visualização").setMessage(body.toString()).setNegativeButton("Cancelar",null).setPositiveButton("Renomear "+list.size()+" ficheiros",(d,w)->runRename(tree,list)).show();}
 void runRename(Uri tree,List<Candidate> list){showProgress(list.size());String prefix=prefixInput.getText()==null?"":prefixInput.getText().toString();String suffix=suffixInput.getText()==null?"":suffixInput.getText().toString();Data d=new Data.Builder().putString("tree",tree.toString()).putString("from",from).putString("to",to).putBoolean("recurse",recursive.isChecked()).putInt("policy",conflict.getSelectedItemPosition()).putString("prefix",prefix).putString("suffix",suffix).build();OneTimeWorkRequest req=new OneTimeWorkRequest.Builder(RenameWorker.class).setInputData(d).addTag("active_rename").build();activeWork=req.getId();WorkManager wm=WorkManager.getInstance(this);wm.enqueueUniqueWork("raw_rename",ExistingWorkPolicy.REPLACE,req);wm.getWorkInfoByIdLiveData(activeWork).observe(this,(WorkInfo info)->{if(info==null)return;Data pg=info.getProgress();int done=pg.getInt("done",0),total=pg.getInt("total",list.size()),pct=pg.getInt("pct",0);if(info.getState()==WorkInfo.State.RUNNING){wave.setProgressCompat(pct,true);percent.setText(pct+"%");progressTitle.setText("A renomear "+done+" de "+total);}if(info.getState().isFinished()){Data o=info.getOutputData();int r=o.getInt("renamed",0),ig=o.getInt("ignored",0),er=o.getInt("errors",0);boolean cancelled=o.getBoolean("cancelled",false);String undo=o.getString("undo");if(undo!=null)getPreferences(MODE_PRIVATE).edit().putString("lastUndo",undo).apply();lastReport="origem,destino,estado\n"+(undo==null?"":undo.replace('|',','));saveHistory(r,ig,er);success(r,ig,er,new ArrayList<>());if(cancelled)progressTitle.setText("Operação cancelada");}});}
 void saveHistory(int r,int i,int e){String line=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date())+"  ."+from+" → ."+to+"  "+r+" renomeados";android.content.SharedPreferences sp=getPreferences(MODE_PRIVATE);String old=sp.getString("history","");sp.edit().putString("history",line+"\n"+old).apply();}
 void exportReport(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"raw-rename-report.csv");startActivityForResult(i,EXPORT);}
 void showProgress(int total){progress=new Dialog(this);progress.setCancelable(false);LinearLayout box=col();box.setPadding(dp(26),dp(24),dp(26),dp(22));box.setBackground(round(surfaceContainer(),28));progressTitle=txt("A preparar ficheiros…",22,true);box.addView(progressTitle);progressRule=txt("Conversão em curso: ."+from.toUpperCase()+" → ."+to.toUpperCase(),14,true);progressRule.setTextColor(primary());box.addView(progressRule,lp(6,14));wave=new LinearProgressIndicator(this);wave.setIndeterminate(false);wave.setMax(100);wave.setProgress(0);wave.setTrackThickness(dp(4));wave.setTrackCornerRadius(dp(2));wave.setIndicatorColor(primary());wave.setTrackColor(secondaryContainer());LinearLayout.LayoutParams waveLayout=new LinearLayout.LayoutParams(-1,dp(20));waveLayout.topMargin=dp(12);waveLayout.bottomMargin=dp(12);box.addView(wave,waveLayout);percent=txt("0%",30,true);percent.setTextColor(primary());percent.setGravity(Gravity.CENTER);box.addView(percent,lp(8,2));MaterialButton cancel=new MaterialButton(this);cancel.setText("Cancelar");cancel.setOnClickListener(v->{if(activeWork!=null)WorkManager.getInstance(this).cancelWorkById(activeWork);});box.addView(cancel,lp(10,0));progress.setContentView(box);progress.show();if(progress.getWindow()!=null){android.view.Window w=progress.getWindow();w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);android.view.WindowManager.LayoutParams a=w.getAttributes();a.dimAmount=.55f;a.width=Math.min((int)(getResources().getDisplayMetrics().widthPixels-dp(48)),dp(560));a.height=android.view.WindowManager.LayoutParams.WRAP_CONTENT;w.setAttributes(a);}}
 void update(int done,int total){runOnUiThread(()->{int p=Math.round(done*100f/Math.max(1,total));wave.setProgress(p/100f);percent.setText(p+"%");progressTitle.setText("A renomear "+done+" de "+total);});}
 void success(int renamed,int ignored,int errors,List<String> details){wave.setProgressCompat(100,true);percent.setText("100%");progressTitle.setText(errors==0?"Processo concluído":"Concluído com avisos");LinearLayout box=(LinearLayout)progressTitle.getParent();TextView result=txt(renamed+" renomeados  •  "+ignored+" ignorados  •  "+errors+" erros",14,false);result.setTextColor(onSurfaceVariant());box.addView(result,lp(6,14));LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.END);MaterialButton export=new MaterialButton(this);export.setText("Exportar CSV");export.setOnClickListener(v->exportReport());actions.addView(export);if(!getPreferences(MODE_PRIVATE).getString("lastUndo","").isEmpty()){MaterialButton undo=new MaterialButton(this);undo.setText("Desfazer");undo.setOnClickListener(v->{progress.dismiss();undoLast();});actions.addView(undo);}MaterialButton ok=new MaterialButton(this);ok.setText("OK");ok.setOnClickListener(v->{progress.dismiss();choose.setEnabled(true);status.setText("Última operação: ."+from+" → ."+to+", "+renamed+" ficheiros");});actions.addView(ok);box.addView(actions);}
 void undoLast(){String raw=getPreferences(MODE_PRIVATE).getString("lastUndo","");new Thread(()->{int restored=0,failed=0;String[] lines=raw.split("\n");for(int n=lines.length-1;n>=0;n--){String[] x=lines[n].split("\\|",4);if(x.length<4)continue;try{Uri dir=Uri.parse(x[0]),item=Uri.parse(x[1]);if(!exists(dir,x[2])&&DocumentsContract.renameDocument(getContentResolver(),item,x[2])!=null)restored++;else failed++;}catch(Exception e){failed++;}}int a=restored,b=failed;getPreferences(MODE_PRIVATE).edit().remove("lastUndo").apply();runOnUiThread(()->{choose.setEnabled(true);new MaterialAlertDialogBuilder(this).setTitle("Desfazer concluído").setMessage(a+" nomes restaurados\n"+b+" não restaurados").setPositiveButton("OK",null).show();status.setText("Última operação desfeita");});}).start();}
 boolean exists(Uri dir,String wanted){Uri ch=DocumentsContract.buildChildDocumentsUriUsingTree(dir,DocumentsContract.getDocumentId(dir));try(android.database.Cursor c=getContentResolver().query(ch,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c!=null)while(c.moveToNext())if(wanted.equalsIgnoreCase(c.getString(0)))return true;}catch(Exception ignored){}return false;}
 String unique(Uri dir,String target){int dot=target.lastIndexOf('.');String base=dot>0?target.substring(0,dot):target,ext=dot>0?target.substring(dot):"";for(int n=1;n<10000;n++){String x=base+"_"+n+ext;if(!exists(dir,x))return x;}return base+"_novo"+ext;}
 String caseExt(String name,String target,String source){String old=name.substring(name.length()-source.length());return old.equals(old.toUpperCase(Locale.ROOT))?target.toUpperCase(Locale.ROOT):target.toLowerCase(Locale.ROOT);}
 String clean(String s){s=s.trim();while(s.startsWith("."))s=s.substring(1);return s;}
 void error(String m){new MaterialAlertDialogBuilder(this).setTitle("Verifica os dados").setMessage(m).setPositiveButton("OK",null).show();}
 LinearLayout col(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;} MaterialCardView card(View child){MaterialCardView c=new MaterialCardView(this);c.setRadius(dp(24));c.setStrokeWidth(dp(1));c.setStrokeColor(outline());c.setCardElevation(0);c.setCardBackgroundColor(surfaceContainer());c.setContentPadding(dp(20),dp(20),dp(20),dp(20));c.addView(child);return c;}
 RadioButton radio(String s,int id,boolean checked){RadioButton r=new RadioButton(this);r.setText(s);r.setId(id);r.setChecked(checked);r.setTextColor(onSurface());r.setButtonTintList(ColorStateList.valueOf(primary()));return r;}
 TextInputLayout inputLayout(String label,String placeholder,boolean source){TextInputLayout l=new TextInputLayout(this);l.setHint(label);l.setPlaceholderText(placeholder);l.setBoxBackgroundMode(TextInputLayout.BOX_BACKGROUND_OUTLINE);l.setBoxCornerRadii(dp(16),dp(16),dp(16),dp(16));TextInputEditText e=new TextInputEditText(this);e.setHint(null);e.setSingleLine(true);e.setPadding(dp(16),0,dp(16),0);l.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));if(label.equals("Origem"))fromInput=e;else if(label.equals("Destino"))toInput=e;return l;}
 TextView txt(String s,int sp,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(onSurface());if(bold)t.setTypeface(null,1);return t;} LinearLayout.LayoutParams lp(int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(top);p.bottomMargin=dp(bottom);return p;}
 android.graphics.drawable.GradientDrawable round(int color,int radius){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}int statusBar(){int id=getResources().getIdentifier("status_bar_height","dimen","android");return id>0?getResources().getDimensionPixelSize(id):dp(24);}
 int attr(int a,int f){TypedValue v=new TypedValue();return getTheme().resolveAttribute(a,v,true)?v.data:f;}int primary(){return attr(com.google.android.material.R.attr.colorPrimary,0xff6750a4);}int onPrimary(){return attr(com.google.android.material.R.attr.colorOnPrimary,Color.WHITE);}int surface(){return attr(com.google.android.material.R.attr.colorSurface,0xfffffbfe);}int surfaceContainer(){return attr(com.google.android.material.R.attr.colorSurfaceContainerHigh,Color.WHITE);}int secondaryContainer(){return attr(com.google.android.material.R.attr.colorSecondaryContainer,0xffe8def8);}int onSecondaryContainer(){return attr(com.google.android.material.R.attr.colorOnSecondaryContainer,0xff1d192b);}int onSurface(){return attr(com.google.android.material.R.attr.colorOnSurface,0xff1d1b20);}int onSurfaceVariant(){return attr(com.google.android.material.R.attr.colorOnSurfaceVariant,0xff49454f);}int outline(){return attr(com.google.android.material.R.attr.colorOutlineVariant,0xffcac4d0);}
}
